from collections import Counter, defaultdict
class Solution:
    def countPairs(self, nums):
        cnt = Counter(nums)
        ans = sum(c * (c - 1) // 2 for c in cnt.values())
        vals = list(cnt)
        buckets = defaultdict(list)
        idxmap = {v: i for i, v in enumerate(vals)}
        def variants(x):
            s = str(x)
            L = len(s)
            pairs = [(i, j) for i in range(L) for j in range(i + 1, L)]
            res = {x}
            for i, j in pairs:
                a = list(s); a[i], a[j] = a[j], a[i]
                t = int(''.join(a)); res.add(t)
                for p, q in pairs:
                    b = a[:]; b[p], b[q] = b[q], b[p]
                    res.add(int(''.join(b)))
            return res
        for v in vals:
            vs = variants(v)
            seen = set()
            for t in vs:
                for u in buckets[t]:
                    seen.add(u)
            ans += len(seen)
            me = idxmap[v]
            for t in vs:
                buckets[t].append(me)
        return ans

