class Solution {
public:
    int countPairs(vector<int>& nums) {
        unordered_map<int,int> cnt;
        for (int x : nums) cnt[x]++;
        long long ans = 0;
        vector<int> vals;
        for (auto& [v, c] : cnt) {
            ans += (long long)c * (c - 1) / 2;
            vals.push_back(v);
        }
        unordered_map<int, vector<int>> buckets;
        auto variants = [&](int x) {
            string s = to_string(x);
            int L = s.size();
            vector<pair<int,int>> pr;
            for (int i = 0; i < L; i++)
                for (int j = i + 1; j < L; j++) pr.push_back({i, j});
            unordered_set<int> res{x};
            for (auto& [i, j] : pr) {
                string a = s; swap(a[i], a[j]);
                res.insert(stoi(a));
                for (auto& [p, q] : pr) {
                    string b = a; swap(b[p], b[q]);
                    res.insert(stoi(b));
                }
            }
            return vector<int>(res.begin(), res.end());
        };
        for (int id = 0; id < (int)vals.size(); id++) {
            auto vs = variants(vals[id]);
            unordered_set<int> seen;
            for (int t : vs)
                for (int u : buckets[t]) seen.insert(u);
            ans += seen.size();
            for (int t : vs) buckets[t].push_back(id);
        }
        return (int)ans;
    }
};

