class Solution {
    public int countPairs(int[] nums) {
        Map<Integer, Integer> cnt = new HashMap<>();
        for (int x : nums) cnt.merge(x, 1, Integer::sum);
        long ans = 0;
        List<Integer> vals = new ArrayList<>();
        for (var e : cnt.entrySet()) {
            ans += (long) e.getValue() * (e.getValue() - 1) / 2;
            vals.add(e.getKey());
        }
        Map<Integer, List<Integer>> buckets = new HashMap<>();
        for (int id = 0; id < vals.size(); id++) {
            String s = String.valueOf(vals.get(id));
            int L = s.length();
            List<int[]> pr = new ArrayList<>();
            for (int i = 0; i < L; i++)
                for (int j = i + 1; j < L; j++) pr.add(new int[]{i, j});
            Set<Integer> vs = new HashSet<>();
            vs.add(Integer.parseInt(s));
            for (int[] ij : pr) {
                char[] a = s.toCharArray();
                char t = a[ij[0]]; a[ij[0]] = a[ij[1]]; a[ij[1]] = t;
                vs.add(Integer.parseInt(new String(a)));
                for (int[] pq : pr) {
                    char[] b = a.clone();
                    char t2 = b[pq[0]]; b[pq[0]] = b[pq[1]]; b[pq[1]] = t2;
                    vs.add(Integer.parseInt(new String(b)));
                }
            }
            Set<Integer> seen = new HashSet<>();
            for (int v : vs) {
                List<Integer> bl = buckets.get(v);
                if (bl != null) seen.addAll(bl);
            }
            ans += seen.size();
            for (int v : vs) buckets.computeIfAbsent(v, k -> new ArrayList<>()).add(id);
        }
        return (int) ans;
    }
}

