var countPairs = function(nums) {
    const cnt = new Map();
    for (const x of nums) cnt.set(x, (cnt.get(x) || 0) + 1);
    let ans = 0;
    const vals = [];
    for (const [v, c] of cnt) {
        ans += c * (c - 1) / 2;
        vals.push(v);
    }
    const buckets = new Map();
    const variants = x => {
        const s = String(x), L = s.length;
        const pr = [];
        for (let i = 0; i < L; i++)
            for (let j = i + 1; j < L; j++) pr.push([i, j]);
        const res = new Set([x]);
        for (const [i, j] of pr) {
            const a = s.split('');
            [a[i], a[j]] = [a[j], a[i]];
            res.add(parseInt(a.join(''), 10));
            for (const [p, q] of pr) {
                const b = a.slice();
                [b[p], b[q]] = [b[q], b[p]];
                res.add(parseInt(b.join(''), 10));
            }
        }
        return [...res];
    };
    vals.forEach((v, id) => {
        const vs = variants(v);
        const seen = new Set();
        for (const t of vs) {
            const bl = buckets.get(t);
            if (bl) for (const u of bl) seen.add(u);
        }
        ans += seen.size;
        for (const t of vs) {
            if (!buckets.has(t)) buckets.set(t, []);
            buckets.get(t).push(id);
        }
    });
    return ans;
};

